       FROM pg_constraint WHERE conrelid = to_regclass('public.creator_record_v2_examination_runs') AND conname = ANY (ARRAY['creator_record_v2_examination_run_environment_project_ref_check', 'creator_record_v2_examination_runs_execution_boundary_check']))
    = '2:8b9b8622ac7134b1fb3e5ca718a3ffae' END),
  ('shape_runs_indexes', (SELECT count(*) || ':' || md5(string_agg(pg_get_indexdef(i.indexrelid), E'\n' ORDER BY c.relname COLLATE "C"))
       FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid WHERE i.indrelid = to_regclass('public.creator_record_v2_examination_runs') AND c.relname = ANY (ARRAY['creator_record_v2_examination_runs_access_log_id_key', 'creator_record_v2_examination_runs_envelope_sha256_key', 'creator_record_v2_examination_runs_examination_key_key', 'creator_record_v2_examination_runs_owner_idx', 'creator_record_v2_examination_runs_pkey', 'creator_record_v2_examination_runs_root_idx', 'creator_record_v2_examination_runs_supersedes_id_key']))
    = '7:1149fb124b3ea3ee4a4e7bfd3b5cf628'),
  ('shape_access_log_purpose', (SELECT count(*) || ':' || md5(string_agg(a.attname || ' ' || format_type(a.atttypid, a.atttypmod) || CASE WHEN a.attnotnull THEN ' not null' ELSE '' END
                 || coalesce(' default ' || pg_get_expr(d.adbin, d.adrelid), ''), E'\n' ORDER BY a.attname COLLATE "C"))
       FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
      WHERE a.attrelid = to_regclass('public.creator_record_v2_evidence_access_log') AND a.attnum > 0 AND NOT a.attisdropped AND a.attname = ANY (ARRAY['purpose']))
    = '1:8c6bd2a71301a96d1b3e92a505be31df'),
  ('shape_access_log_purpose_check', (SELECT count(*) || ':' || md5(string_agg(conname || ': ' || pg_get_constraintdef(oid), E'\n' ORDER BY conname COLLATE "C"))
       FROM pg_constraint WHERE conrelid = to_regclass('public.creator_record_v2_evidence_access_log') AND conname = ANY (ARRAY['creator_record_v2_evidence_access_log_purpose_check']))
    = '1:a50e874577291427d7ee41c14e9bad5e'),
  -- Data: no examination authority, nothing examined, the 45 committed fixtures, DOC-1 rows all downloads,
  ('marker_rows_0', CASE WHEN to_regclass('public.creator_record_v2_examination_environment') IS NULL THEN NULL ELSE
       (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.creator_record_v2_examination_environment', false, true, '')))[1]::text = '0' END),
  ('runs_rows_0', CASE WHEN to_regclass('public.creator_record_v2_examination_runs') IS NULL THEN NULL ELSE
       (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.creator_record_v2_examination_runs', false, true, '')))[1]::text = '0' END),
  ('fixtures_rows_45', CASE WHEN to_regclass('public.creator_record_v2_synthetic_fixtures') IS NULL THEN NULL ELSE
       (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.creator_record_v2_synthetic_fixtures WHERE fixture_set = ''receipt-fixtures-v2/oracle-replay''', false, true, '')))[1]::text = '45' END),
  ('access_log_all_downloads', CASE WHEN NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'public.creator_record_v2_evidence_access_log'::regclass AND attname = 'purpose' AND attnum > 0 AND NOT attisdropped) THEN NULL ELSE
       (xpath('/row/n/text()', query_to_xml('SELECT count(*) AS n FROM public.creator_record_v2_evidence_access_log WHERE purpose <> ''file_download''', false, true, '')))[1]::text = '0' END),
  -- Security, DOC-1 boundary (these must already pass before 20261104000000: 01 refuses otherwise), exact,
  ('doc1_table_privileges', (SELECT coalesce(array_agg(t.tbl || ':' || r.role || ':' || p.priv ORDER BY t.tbl || ':' || r.role || ':' || p.priv COLLATE "C"), ARRAY[]::text[])
       FROM unnest(ARRAY['creator_record_v2_documents', 'creator_record_v2_evidence_access_log', 'creator_record_v2_prepared_documents']) t(tbl), unnest(ARRAY['anon', 'authenticated', 'public', 'service_role']) r(role), unnest(ARRAY['DELETE', 'INSERT', 'REFERENCES', 'SELECT', 'TRIGGER', 'TRUNCATE', 'UPDATE'] || CASE WHEN current_setting('server_version_num')::int >= 170000 THEN ARRAY['MAINTAIN'] ELSE ARRAY[]::text[] END) p(priv)
      WHERE coalesce(has_table_privilege(r.role, to_regclass('public.' || t.tbl), p.priv), false))
    = ARRAY['creator_record_v2_documents:service_role:DELETE', 'creator_record_v2_documents:service_role:INSERT', 'creator_record_v2_documents:service_role:SELECT', 'creator_record_v2_documents:service_role:UPDATE', 'creator_record_v2_evidence_access_log:service_role:INSERT', 'creator_record_v2_evidence_access_log:service_role:SELECT', 'creator_record_v2_prepared_documents:service_role:SELECT']),
  ('doc1_rls_on', (SELECT count(*) FROM pg_class WHERE oid = ANY (ARRAY[to_regclass('public.creator_record_v2_documents'), to_regclass('public.creator_record_v2_evidence_access_log'), to_regclass('public.creator_record_v2_prepared_documents')]::oid[]) AND relrowsecurity) = 3),
  ('doc1_no_policies', NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = ANY (ARRAY[to_regclass('public.creator_record_v2_documents'), to_regclass('public.creator_record_v2_evidence_access_log'), to_regclass('public.creator_record_v2_prepared_documents')]::oid[]))),
  ('doc1_triggers_enabled', (SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid WHERE t.tgenabled = 'O' AND NOT t.tgisinternal AND (c.relname, t.tgname) IN (
       ('creator_record_v2_documents', 'creator_record_v2_documents_guard'), ('creator_record_v2_evidence_access_log', 'creator_record_v2_evidence_access_log_append_only'),
       ('creator_record_v2_prepared_documents', 'creator_record_v2_prepared_documents_append_only'), ('creator_record_v2_prepared', 'creator_record_v2_prepared_documents_link'))) = 4),
  ('doc1_function_modes', (SELECT coalesce(array_agg(f.sig || ':' || CASE WHEN p.prosecdef THEN 'definer' ELSE 'invoker' END || ':' || coalesce(array_to_string(p.proconfig, ';'), '-') ORDER BY f.sig COLLATE "C"), ARRAY[]::text[])
       FROM unnest(ARRAY['creator_record_v2_append_only_guard()', 'creator_record_v2_documents_guard()', 'creator_record_v2_prepared_documents_link()']) f(sig) JOIN pg_proc p ON p.oid = to_regprocedure('public.' || f.sig))
    = ARRAY['creator_record_v2_append_only_guard():invoker:-', 'creator_record_v2_documents_guard():invoker:-', 'creator_record_v2_prepared_documents_link():definer:search_path=public, pg_temp']),
  ('doc1_function_execute', (SELECT coalesce(array_agg(f.sig || ':' || r.role ORDER BY f.sig || ':' || r.role COLLATE "C"), ARRAY[]::text[])
       FROM unnest(ARRAY['creator_record_v2_append_only_guard()', 'creator_record_v2_documents_guard()', 'creator_record_v2_prepared_documents_link()']) f(sig), unnest(ARRAY['anon', 'authenticated', 'public', 'service_role']) r(role)
      WHERE coalesce(has_function_privilege(r.role, to_regprocedure('public.' || f.sig), 'EXECUTE'), false))
    = ARRAY[]::text[]),
  ('doc1_function_bodies', (SELECT count(*) = 3 FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND (p.proname::text, md5(p.prosrc)) IN (
       ('creator_record_v2_append_only_guard', '853241fdf43eebd7a783cc6b633bc1dd'), ('creator_record_v2_append_only_guard', '509db484094209260f0378431fe917f8'),
       ('creator_record_v2_documents_guard', '16acef5be434a536c6527f05a5c64cb7'), ('creator_record_v2_documents_guard', 'c7137201b1f6bcf2e7f7f871a0b9ccb3'),
       ('creator_record_v2_prepared_documents_link', '98f1183d8e42468347e10f8de1c1a15b'), ('creator_record_v2_prepared_documents_link', 'cf2fee7f2acf902eaef69dd0cc2dee9c')))),
  -- Security, 20261104000000 objects, exact; triggers exact on every protected table,
  ('table_privileges', (SELECT coalesce(array_agg(t.tbl || ':' || r.role || ':' || p.priv ORDER BY t.tbl || ':' || r.role || ':' || p.priv COLLATE "C"), ARRAY[]::text[])
       FROM unnest(ARRAY['creator_record_v2_examination_environment', 'creator_record_v2_synthetic_fixtures', 'creator_record_v2_examination_runs']) t(tbl), unnest(ARRAY['anon', 'authenticated', 'public', 'service_role']) r(role), unnest(ARRAY['DELETE', 'INSERT', 'REFERENCES', 'SELECT', 'TRIGGER', 'TRUNCATE', 'UPDATE'] || CASE WHEN current_setting('server_version_num')::int >= 170000 THEN ARRAY['MAINTAIN'] ELSE ARRAY[]::text[] END) p(priv)
      WHERE coalesce(has_table_privilege(r.role, to_regclass('public.' || t.tbl), p.priv), false))
    = ARRAY['creator_record_v2_examination_runs:service_role:SELECT', 'creator_record_v2_synthetic_fixtures:service_role:SELECT']),
  ('rls_on', (SELECT count(*) FROM pg_class WHERE oid = ANY (ARRAY[to_regclass('public.creator_record_v2_examination_environment'), to_regclass('public.creator_record_v2_synthetic_fixtures'), to_regclass('public.creator_record_v2_examination_runs')]::oid[]) AND relrowsecurity) = 3),
  ('no_policies', NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid = ANY (ARRAY[to_regclass('public.creator_record_v2_examination_environment'), to_regclass('public.creator_record_v2_synthetic_fixtures'), to_regclass('public.creator_record_v2_examination_runs')]::oid[]))),
  ('triggers', (SELECT coalesce(array_agg(c.relname || ':' || t.tgname || ':' || t.tgenabled::text ORDER BY c.relname || ':' || t.tgname COLLATE "C"), ARRAY[]::text[])
       FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid WHERE NOT t.tgisinternal AND c.oid = ANY (ARRAY[to_regclass('public.creator_record_v2_documents'), to_regclass('public.creator_record_v2_evidence_access_log'), to_regclass('public.creator_record_v2_prepared_documents'), to_regclass('public.creator_record_v2_examination_environment'), to_regclass('public.creator_record_v2_synthetic_fixtures'), to_regclass('public.creator_record_v2_examination_runs')]::oid[]))
    = CASE WHEN to_regclass('public.creator_record_v2_examination_uat_grants') IS NOT NULL THEN ARRAY['creator_record_v2_documents:creator_record_v2_documents_guard:O', 'creator_record_v2_documents:creator_record_v2_documents_provenance_guard:O', 'creator_record_v2_documents:creator_record_v2_documents_seed_binding:O', 'creator_record_v2_evidence_access_log:creator_record_v2_evidence_access_log_append_only:O', 'creator_record_v2_evidence_access_log:creator_record_v2_evidence_access_log_insert_guard:O', 'creator_record_v2_examination_environment:creator_record_v2_examination_environment_exclusivity:O', 'creator_record_v2_examination_environment:creator_record_v2_examination_environment_guard:O', 'creator_record_v2_examination_runs:creator_record_v2_examination_runs_append_only:O', 'creator_record_v2_prepared_documents:creator_record_v2_prepared_documents_append_only:O', 'creator_record_v2_prepared_documents:creator_record_v2_prepared_documents_origin_guard:O', 'creator_record_v2_synthetic_fixtures:creator_record_v2_synthetic_fixtures_append_only:O']
      ELSE ARRAY['creator_record_v2_documents:creator_record_v2_documents_guard:O', 'creator_record_v2_evidence_access_log:creator_record_v2_evidence_access_log_append_only:O', 'creator_record_v2_evidence_access_log:creator_record_v2_evidence_access_log_insert_guard:O', 'creator_record_v2_examination_environment:creator_record_v2_examination_environment_guard:O', 'creator_record_v2_examination_runs:creator_record_v2_examination_runs_append_only:O', 'creator_record_v2_prepared_documents:creator_record_v2_prepared_documents_append_only:O', 'creator_record_v2_synthetic_fixtures:creator_record_v2_synthetic_fixtures_append_only:O'] END),
  ('table_owner', (SELECT count(*) FROM pg_class WHERE oid = ANY (ARRAY[to_regclass('public.creator_record_v2_examination_environment'), to_regclass('public.creator_record_v2_synthetic_fixtures'), to_regclass('public.creator_record_v2_examination_runs')]::oid[]) AND relowner = (SELECT relowner FROM pg_class WHERE oid = 'public.creator_record_v2_documents'::regclass)) = 3),
  ('function_modes', (SELECT coalesce(array_agg(f.sig || ':' || CASE WHEN p.prosecdef THEN 'definer' ELSE 'invoker' END || ':' || coalesce(array_to_string(p.proconfig, ';'), '-') ORDER BY f.sig COLLATE "C"), ARRAY[]::text[])
       FROM unnest(ARRAY['creator_record_v2_jsonb_exact_keys(jsonb,text[])', 'creator_record_v2_examination_environment_guard()', 'creator_record_v2_examination_append_only_guard()', 'creator_record_v2_evidence_access_log_insert_guard()', 'creator_record_v2_record_examination(bigint,text)']) f(sig) JOIN pg_proc p ON p.oid = to_regprocedure('public.' || f.sig))
    = ARRAY['creator_record_v2_evidence_access_log_insert_guard():definer:search_path=public, pg_temp', 'creator_record_v2_examination_append_only_guard():invoker:search_path=public, pg_temp', 'creator_record_v2_examination_environment_guard():invoker:search_path=public, pg_temp', 'creator_record_v2_jsonb_exact_keys(jsonb,text[]):invoker:search_path=public, pg_temp', 'creator_record_v2_record_examination(bigint,text):definer:search_path=public, pg_temp']),
  ('function_owner', (SELECT count(*) FROM unnest(ARRAY['creator_record_v2_jsonb_exact_keys(jsonb,text[])', 'creator_record_v2_examination_environment_guard()', 'creator_record_v2_examination_append_only_guard()', 'creator_record_v2_evidence_access_log_insert_guard()', 'creator_record_v2_record_examination(bigint,text)']) f(sig) JOIN pg_proc p ON p.oid = to_regprocedure('public.' || f.sig)
      WHERE p.proowner = (SELECT relowner FROM pg_class WHERE oid = 'public.creator_record_v2_documents'::regclass)) = 5),
  ('function_execute', (SELECT coalesce(array_agg(f.sig || ':' || r.role ORDER BY f.sig || ':' || r.role COLLATE "C"), ARRAY[]::text[])
       FROM unnest(ARRAY['creator_record_v2_jsonb_exact_keys(jsonb,text[])', 'creator_record_v2_examination_environment_guard()', 'creator_record_v2_examination_append_only_guard()', 'creator_record_v2_evidence_access_log_insert_guard()', 'creator_record_v2_record_examination(bigint,text)']) f(sig), unnest(ARRAY['anon', 'authenticated', 'public', 'service_role']) r(role)
      WHERE coalesce(has_function_privilege(r.role, to_regprocedure('public.' || f.sig), 'EXECUTE'), false))
    = ARRAY['creator_record_v2_record_examination(bigint,text):service_role'])
) AS t(name, ok)
  ) x;
  IF v->>'state' IS DISTINCT FROM 'applied' OR (v->>'all_pass')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'D1A post-check failed; nothing is committed: %', v;
  END IF;
END
